refentry.refsect1:
  &reftitle.examples;

   Using the keys as the string representation


<?php
$iterator = new CachingIterator(
    new ArrayIterator(['apple' => 3, 'banana' => 5]),
    CachingIterator::TOSTRING_USE_KEY
);

foreach ($iterator as $count) {
    echo $iterator, ': ', $count, "\n";
}
?>


   &example.outputs;


apple: 3
banana: 5
